  2	
  3	import java.util.LinkedHashMap;
  4	import java.util.List;
  5	import java.util.Map;
  6	import java.util.Optional;
  7	
  8	public class ShippingOptions {
  9	    private final Map<String, ShippingOption> byCode = new LinkedHashMap<>();
 10	
 11	    public ShippingOptions(List<ShippingOption> options) {
 12	        options.forEach(o -> byCode.put(o.code(), o));
 13	    }
 14	
 15	    /** Opções de hoje; uma nova opção de entrega entra nesta lista. */
 16	    public static ShippingOptions standard(CarrierClient carrier) {
 17	        return new ShippingOptions(List.of(
 18	                new CarrierShipping("ECONOMY", "STD", carrier),
 19	                new CarrierShipping("EXPRESS", "EXP", carrier),
 20	                new StorePickup(),
 21	                new Courier()));
 22	    }
 23	
 24	    public Optional<ShippingOption> find(String code) {
 25	        return Optional.ofNullable(code).map(byCode::get);
 26	    }
 27	}
 28	package shop.domain.shipping;
 29	
 30	import java.math.BigDecimal;
 31	import shop.domain.DomainException;
 32	import shop.domain.ErrorCode;
 33	
 34	/** Entrega cotada na transportadora (econômica e expressa). */
 35	public class CarrierShipping implements ShippingOption {
 36	    private final String code;
 37	    private final String carrierService;
 38	    private final CarrierClient client;
 39	
 40	    public CarrierShipping(String code, String carrierService, CarrierClient client) {
 41	        this.code = code;
 42	        this.carrierService = carrierService;
 43	        this.client = client;
 44	    }
 45	
 46	    @Override
 47	    public String code() {
 48	        return code;
 49	    }
 50	
 51	    @Override
 52	    public ShippingQuote quote(ShippingRequest request) {
 53	        long grams = request.weightKg().movePointRight(3).longValue();
 54	        try {
 55	            CarrierClient.CarrierQuote quote = client.quote(request.zipCode(), grams, carrierService);
 56	            int days = (quote.etaHours() + 23) / 24 + request.region().extraCarrierDays();
 57	            return new ShippingQuote(new BigDecimal(quote.priceCents()).movePointLeft(2), days);
 58	        } catch (CarrierClient.ZipNotServedException e) {
 59	            throw new DomainException(ErrorCode.SHIPPING_METHOD_UNAVAILABLE);
 60	        } catch (CarrierClient.CarrierDownException e) {
 61	            throw new DomainException(ErrorCode.CARRIER_UNAVAILABLE);
 62	        }
 63	    }
 64	
 65	    @Override
 66	    public boolean chargesFreight() {
 67	        return true;
 68	    }
 69	
 70	    @Override
 71	    public boolean clubWaivable() {
 72	        return true;
 73	    }
 74	}
 75	package shop.domain.shipping;
 76	
 77	import java.math.BigDecimal;
 78	import shop.domain.DomainException;
 79	import shop.domain.ErrorCode;
 80	import shop.domain.Money;
 81	
 82	public class Courier implements ShippingOption {
 83	    private static final BigDecimal MAX_WEIGHT_KG = new BigDecimal("5");
 84	    private static final BigDecimal COST = Money.of("18.00");
 85	
 86	    @Override
 87	    public String code() {
 88	        return "COURIER";
 89	    }
 90	
 91	    @Override
 92	    public ShippingQuote quote(ShippingRequest request) {
 93	        if (request.weightKg().compareTo(MAX_WEIGHT_KG) > 0) {
 94	            throw new DomainException(ErrorCode.SHIPPING_METHOD_UNAVAILABLE);
 95	        }
 96	        return new ShippingQuote(COST, 0);
 97	    }
 98	
 99	    @Override
100	    public boolean chargesFreight() {
101	        return true;
102	    }
103	
104	    /** Motoboy é terceirizado: o clube não cobre o frete. */
105	    @Override
106	    public boolean clubWaivable() {
107	        return false;
108	    }
109	}
110	package shop.domain.shipping;
111	
112	import shop.domain.Money;
113	
114	public class StorePickup implements ShippingOption {
115	    @Override
116	    public String code() {
117	        return "STORE_PICKUP";
118	    }
119	
120	    @Override
121	    public ShippingQuote quote(ShippingRequest request) {
122	        return new ShippingQuote(Money.ZERO, 1);
123	    }
124	
125	    @Override
126	    public boolean chargesFreight() {
127	        return false;
128	    }
129	
130	    @Override
131	    public boolean clubWaivable() {
132	        return true;
133	    }
134	}
135	package shop.domain.shipping;
136	
137	/** Uma forma de entrega. Uma nova opção é uma nova implementação registrada em {@link ShippingOptions}. */
138	public interface ShippingOption {
139	    String code();
140	
141	    /** Lança DomainException se a opção não atende o pedido. */
142	    ShippingQuote quote(ShippingRequest request);
143	
144	    /** Se existe frete a cobrar (a retirada na loja não tem). */
145	    boolean chargesFreight();
146	
147	    /** Se o benefício de frete grátis do clube vale nesta opção. */
148	    boolean clubWaivable();
149	}
150	package shop.domain.shipping;
151	
152	/** Porta para a transportadora; trocar de transportadora é trocar a implementação. */
153	public interface CarrierClient {
154	    CarrierQuote quote(String zipCode, long weightGrams, String service);
155	
156	    record CarrierQuote(long priceCents, int etaHours) {
157	    }
158	
159	    class ZipNotServedException extends RuntimeException {
160	        public ZipNotServedException() {
161	            super("ZIP_NOT_SERVED", null, false, false);
162	        }
163	    }
164	
165	    class CarrierDownException extends RuntimeException {
166	        public CarrierDownException(String message, Throwable cause) {
167	            super(message, cause);
168	        }
169	    }
170	}

