 10	public class Coupons {
 11	    /** Nenhum cupom pode passar de 30% do valor dos produtos. */
 12	    private static final BigDecimal MAX_DISCOUNT_PERCENT = new BigDecimal("30");
 13	
 14	    private final Map<String, Coupon> byCode = new LinkedHashMap<>();
 15	
 16	    public Coupons(List<Coupon> coupons) {
 17	        coupons.forEach(c -> byCode.put(c.code(), c));
 18	    }
 19	
 20	    /** Cupons de hoje; uma nova promoção entra nesta lista. */
 21	    public static Coupons standard() {
 22	        return new Coupons(List.of(new Welcome10(), new Minus50(), new FreeShipping(), new Buy3Pay2()));
 23	    }
 24	
 25	    public Optional<Coupon> find(String code) {
 26	        return Optional.ofNullable(code).map(byCode::get);
 27	    }
 28	
 29	    public static BigDecimal cap(BigDecimal discount, BigDecimal productsSubtotal) {
 30	        BigDecimal max = Money.percent(productsSubtotal, MAX_DISCOUNT_PERCENT);
 31	        return Money.round(discount.min(max));
 32	    }
 33	}
