116	import java.time.Clock;
117	import java.time.Instant;
118	import java.time.temporal.ChronoUnit;
119	import java.util.UUID;
120	import shop.domain.CartItem;
121	import shop.domain.Order;
122	import shop.domain.OrderStatus;
123	import shop.domain.Summary;
124	import shop.persistence.Store;
125	
126	public class CheckoutService {
127	    private final Store store;
128	    private final CheckoutCalculator calculator;
129	    private final Clock clock;
130	
131	    public CheckoutService(Store store, CheckoutCalculator calculator, Clock clock) {
132	        this.store = store;
133	        this.calculator = calculator;
134	        this.clock = clock;
135	    }
136	
137	    public Summary summary(CheckoutRequest request) {
138	        return store.inTransaction(tx -> calculator.calculate(request, tx));
139	    }
140	
141	    public Order register(CheckoutRequest request) {
142	        return store.inTransaction(tx -> {
143	            Summary summary = calculator.calculate(request, tx);
144	            tx.customers().ensure(request.cpf());
145	            Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
146	                    Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary,
147	                    request.items().stream().map(i -> new CartItem(i.sku(), i.quantity())).toList(), null,
148	                    request.cpf());
149	            tx.orders().insert(order);
150	            return order;
151	        });
152	    }
153	}
