185	import java.math.BigDecimal;
186	import java.math.MathContext;
187	import java.math.RoundingMode;
188	import shop.domain.Money;
189	
190	public class CreditCard implements PaymentMethod {
191	    private static final int MAX_INSTALLMENTS = 12;
192	    private static final int MAX_INTEREST_FREE = 3;
193	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
194	    private static final MathContext MC = new MathContext(30, RoundingMode.HALF_EVEN);
195	
196	    @Override
197	    public String code() {
198	        return "CREDIT_CARD";
199	    }
200	
201	    @Override
202	    public boolean acceptsInstallments(int installments) {
203	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
204	    }
205	
206	    @Override
207	    public boolean availableFor(BigDecimal orderTotal) {
208	        return true;
209	    }
210	
211	    @Override
212	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
213	        BigDecimal n = BigDecimal.valueOf(installments);
214	        if (installments <= MAX_INTEREST_FREE) {
215	            return new PaymentCharge(orderTotal, Money.round(orderTotal.divide(n, MC)));
216	        }
217	        // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
218	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(installments);
219	        BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MC));
220	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE).divide(denominator, MC));
221	        return new PaymentCharge(installment.multiply(n), installment);
222	    }
223	}
